function validate(input) {
  const [{ Tree = [] }] = input;
  const parent = new Map(), children = new Map();
  let roots = 0;
  for (const [n, p] of Tree) {
    if (n === null) return 'Every row needs a node value N.';
    if (parent.has(n)) return `Node ${n} appears twice.`;
    parent.set(n, p);
    if (p === null) roots++;
  }
  if (Tree.length && roots !== 1) return 'The tree needs exactly one root (P = null).';
  for (const [n, p] of Tree) {
    if (p === null) continue;
    if (!parent.has(p)) return `Parent ${p} of node ${n} is not in the table.`;
    children.set(p, (children.get(p) ?? 0) + 1);
    if (children.get(p) > 2) return `Node ${p} has more than two children.`;
  }
  // Walking up from every node must reach the root without revisiting a node.
  const reaches = new Map();
  for (const [n] of Tree) {
    const path = [];
    let cur = n;
    while (cur !== null && !reaches.has(cur)) {
      if (path.includes(cur)) return `Node ${cur} is its own ancestor.`;
      path.push(cur);
      cur = parent.get(cur);
    }
    for (const v of path) reaches.set(v, true);
  }
  return null;
}

