function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const count = size === 'small' ? pick(9) : 1500 + pick(500);
  // Distinct node values, drawn from a small range for small trees so they look like Example 1.
  const range = size === 'small' ? 20 : 100000;
  const values = new Set();
  while (values.size < count) values.add(1 + pick(range));
  const nodes = [...values];
  const Tree = [], open = [];
  nodes.forEach((n, i) => {
    if (i === 0) { Tree.push([n, null]); open.push([n, 2]); return; }
    // Attach to a random node that still has a free child slot; long chains and full nodes both happen.
    const k = pick(open.length);
    const slot = open[k];
    Tree.push([n, slot[0]]);
    if (--slot[1] === 0) { open[k] = open[open.length - 1]; open.pop(); }
    open.push([n, 2]);
  });
  for (let i = Tree.length - 1; i > 0; i--) { const j = pick(i + 1); [Tree[i], Tree[j]] = [Tree[j], Tree[i]]; }
  return [{ Tree }];
}
